const items = [0, 1, 2, 3].map(i => root.querySelector('#c' + i));
const paths = [1, 2, 3].map(i => {
  const el = root.querySelector('#l' + i);
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});

function frame(t, p, d) {
  const curT = Math.min(t, d * 0.55);

  // Hub: Gemini Agent
  const s0 = spr(curT, 0.1, 0.8, 10);
  items[0].style.opacity = clamp((curT - 0.1) * 4);
  items[0].style.transform = `scale(${s0})`;

  // Paths 1 & 2 branching out
  const p12 = clamp((curT - 0.8) * 2.5);
  paths[0].el.style.strokeDashoffset = paths[0].len * (1 - E_OUT(p12));
  paths[1].el.style.strokeDashoffset = paths[1].len * (1 - E_OUT(p12));

  // Action Cards (Move Files / Enter Data)
  [1, 2].forEach((idx) => {
    const delay = 1.3 + (idx * 0.15);
    const s = spr(curT, delay, 0.8, 10);
    items[idx].style.opacity = clamp((curT - delay) * 4);
    items[idx].style.transform = `scale(${s})`;
  });

  // Path 3 down to Control
  const p3 = clamp((curT - 2.0) * 2.5);
  paths[2].el.style.strokeDashoffset = paths[2].len * (1 - E_OUT(p3));

  // Control Card: Pause/Stop
  const s3 = spr(curT, 2.5, 0.8, 10);
  items[3].style.opacity = clamp((curT - 2.5) * 4);
  items[3].style.transform = `scale(${s3})`;
}
